"""ARENA u05 的 10 道测验（沿用旧版题目，调整了解释措辞）"""
from unitlib import Q
QUIZ = [
  Q('两个**共线**的二维向量（比如 $(1, 2)$ 和 $(2, 4)$）的张成空间是什么？', ['整个二维平面', '一条经过原点的直线', '只有原点', '一个正方形区域'], 1, '$(2, 4) = 2 \\times (1, 2)$，两者线性相关，所有组合都落在同一条直线上。'),
  Q('下面哪组向量是二维空间的一组**基**？', ['$(1, 0)$ 和 $(2, 0)$', '$(0, 0)$ 和 $(1, 1)$', '$(1, 1)$ 和 $(1, -1)$', '只有 $(1, 1)$'], 2, '$(1,1)$ 和 $(1,-1)$ 不共线（线性无关），能张成整个平面。$(1,0)$ 和 $(2,0)$ 共线；含零向量的组合必然线性相关；只有一个向量，张不满二维。'),
  Q('$n$ 维空间的一组基里有几个向量？', ['恰好 $n$ 个', '至少 $n+1$ 个', '任意多个', '取决于选哪组基'], 0, '任何一组基的向量个数都相同，等于空间的维数 $n$。'),
  Q('$(1, 2, 3) \\cdot (4, -1, 2)$ 等于？', ['12', '0', '6', '8'], 3, '$1 \\times 4 + 2 \\times (-1) + 3 \\times 2 = 4 - 2 + 6 = 8$。'),
  Q('两个非零向量的点积为 0，说明什么？', ['它们方向相同', '它们互相垂直（正交）', '其中一个是零向量', '它们长度相等'], 1, '$\\mathbf{u}\\cdot\\mathbf{v} = \\|\\mathbf{u}\\|\\|\\mathbf{v}\\|\\cos\\theta = 0$，而长度都不为 0，所以 $\\cos\\theta = 0$，夹角 90°。'),
  Q('$\\mathbf{u} = (1, 0)$，$\\mathbf{v} = (1, 1)$，余弦相似度是多少？', ['$1$', '$0$', '$\\sqrt{2}$', '$1/\\sqrt{2} \\approx 0.707$'], 3, '点积为 1，长度分别为 1 和 $\\sqrt{2}$，所以 $\\cos\\theta = 1/\\sqrt{2}$，夹角 45°。'),
  Q('矩阵 $B$ 的列是一组新基（用标准坐标写出）。一个向量在新基下的坐标是 $\\mathbf{c}$，它在标准坐标下是？', ['$B\\mathbf{c}$', '$B^{-1}\\mathbf{c}$', '$B^\\top\\mathbf{c}$', '$\\mathbf{c}$ 本身'], 0, '新基坐标 $\\mathbf{c} = (x, y)$ 的意思是 $x\\mathbf{b}_1 + y\\mathbf{b}_2$，也就是 $B\\mathbf{c}$。反方向（标准 → 新基）才用 $B^{-1}$。'),
  Q('变换 $M$ 用标准坐标写出，基变换矩阵为 $B$。在新基坐标下，同一个变换的矩阵是？', ['$BMB^{-1}$', '$B^{-1}MB$', '$MB$', '$B^\\top M$'], 1, '从右往左：先用 $B$ 把新基坐标翻译成标准坐标，再做 $M$，最后用 $B^{-1}$ 翻译回新基坐标。'),
  Q('关于**正交矩阵** $Q$，下面哪个说法正确？', ['它的所有元素都是 0 或 1', '它的行列式一定为 0', '它的逆矩阵等于它的转置，并且保持向量的长度', '它一定是对称矩阵'], 2, '$Q^\\top Q = I$ 意味着 $Q^{-1} = Q^\\top$；它把向量长度和夹角都保持不变（旋转或反射），行列式为 ±1。'),
  Q('矩阵 $\\begin{bmatrix} 0 & -1 \\\\ 1 & 0 \\end{bmatrix}$ 是哪一类？', ['对称矩阵', '奇异矩阵（不可逆）', '单位矩阵', '旋转矩阵（逆时针 90°），也是正交矩阵'], 3, '代入 $\\theta = 90°$：$\\cos\\theta = 0$，$\\sin\\theta = 1$。它的转置是它的逆（顺时针转回去）；它不对称，因为转置后 $-1$ 和 $1$ 互换了位置。'),
]
